/// story just before it, or, where there is none, a new story of its own.
pub fn draft_proposals(about: &str, proposals: Vec<Proposal>) -> Vec<Proposal> {
    let mut stories: Vec<Proposal> = Vec::new();
    for mut proposal in proposals {
